record.field:
doc_type_model = env['x_hr.recruitment_required_document_type'].sudo()
checklist_model = env['x_hr.applicant_required_document_checklist'].sudo()
line_model = env['x_hr.applicant_required_document_line'].sudo()

active_types = doc_type_model.search([
    ('x_active', '=', True),
], order='x_sequence asc, id asc')

if not active_types:
    raise Warning('No active F-0003 required document types were found. Please check the required document type seed data.')

now = datetime.datetime.now()

for applicant in records:
    checklist = checklist_model.search([
        ('x_applicant_id', '=', applicant.id),
        ('x_state', 'not in', ['cancelled', 'signed']),
    ], order='id desc', limit=1)

    created_checklist = False

    if not checklist:
        applicant_name = applicant.partner_name or applicant.name or applicant.display_name or 'Applicant'
        checklist_sequence = checklist_model.search_count([
            ('x_applicant_id', '=', applicant.id),
        ]) + 1
        checklist_reference = 'MCEP-HR-F-0003-%05d-%02d' % (applicant.id, checklist_sequence)
        checklist = checklist_model.create({
            'x_name': '%s / F-0003 Checklist #%s / %s / Draft' % (
                applicant_name,
                checklist_sequence,
                checklist_reference,
            ),
            'x_applicant_id': applicant.id,
            'x_checklist_sequence': checklist_sequence,
            'x_state': 'draft',
            'x_document_reference': checklist_reference,
            'x_prepared_by_user_id': env.user.id,
            'x_prepared_on': now,
            'x_reviewer_user_id': env.user.id,
            'x_notes': 'F-0003 checklist prepared from the active required document type library.',
        })
        created_checklist = True

    existing_type_ids = checklist.x_line_ids.mapped('x_document_type_id').ids
    added_count = 0

    for doc_type in active_types:
        if doc_type.id not in existing_type_ids:
            line_model.create({
                'x_name': doc_type.x_name,
                'x_checklist_id': checklist.id,
                'x_document_type_id': doc_type.id,
                'x_sequence': doc_type.x_sequence or 0,
                'x_document_name_ar': doc_type.x_name_ar,
                'x_document_name_en': doc_type.x_name_en,
                'x_document_code': doc_type.x_code,
                'x_fillout_prefix': doc_type.x_fillout_prefix or doc_type.x_code,
                'x_required': doc_type.x_required,
                'x_status': 'missing',
                'x_capture_scope': doc_type.x_capture_scope or 'none',
                'x_public_request_enabled': doc_type.x_public_request_enabled,
                'x_requires_attachment': doc_type.x_requires_attachment,
                'x_manual_review_expected': doc_type.x_manual_review_expected,
                'x_structured_data_required': doc_type.x_structured_data_required,
                'x_notes': doc_type.x_notes,
            })
            added_count += 1

    # Normalize checklist-line snapshots from the current document type library.
    # This is intentionally additive/non-destructive: it updates snapshot metadata
    # but does not delete historical lines.
    for line in checklist.x_line_ids:
        doc_type = line.x_document_type_id
        if not doc_type:
            continue

        line_values = {}
        if line.x_sequence != (doc_type.x_sequence or 0):
            line_values['x_sequence'] = doc_type.x_sequence or 0
        if line.x_document_name_ar != doc_type.x_name_ar:
            line_values['x_document_name_ar'] = doc_type.x_name_ar
        if line.x_document_name_en != doc_type.x_name_en:
            line_values['x_document_name_en'] = doc_type.x_name_en
        if line.x_document_code != doc_type.x_code:
            line_values['x_document_code'] = doc_type.x_code
        if line.x_fillout_prefix != (doc_type.x_fillout_prefix or doc_type.x_code):
            line_values['x_fillout_prefix'] = doc_type.x_fillout_prefix or doc_type.x_code
        if line.x_capture_scope != (doc_type.x_capture_scope or 'none'):
            line_values['x_capture_scope'] = doc_type.x_capture_scope or 'none'
        if line.x_public_request_enabled != doc_type.x_public_request_enabled:
            line_values['x_public_request_enabled'] = doc_type.x_public_request_enabled
        if line.x_requires_attachment != doc_type.x_requires_attachment:
            line_values['x_requires_attachment'] = doc_type.x_requires_attachment
        if line.x_manual_review_expected != doc_type.x_manual_review_expected:
            line_values['x_manual_review_expected'] = doc_type.x_manual_review_expected
        if line.x_structured_data_required != doc_type.x_structured_data_required:
            line_values['x_structured_data_required'] = doc_type.x_structured_data_required

        # Retire the old combined identity row on editable checklists only.
        # The row is kept for upgrade safety but should not remain a required
        # public or signed checklist line after the split into passport/id card/license.
        if doc_type.x_code == 'identity_document_copy' and line.x_status != 'accepted':
            line_values.update({
                'x_required': False,
                'x_status': 'not_applicable',
                'x_public_request_enabled': False,
                'x_requires_attachment': False,
                'x_manual_review_expected': False,
                'x_structured_data_required': False,
            })
            legacy_note = 'Legacy combined identity row replaced by separate passport, ID card, and driving license lines.'
            if legacy_note not in (line.x_notes or ''):
                line_values['x_notes'] = ((line.x_notes or '') + '\n' + legacy_note).strip()

        if line_values:
            line.write(line_values)

    if created_checklist:
        applicant.message_post(
            body='F-0003 Required Documents Checklist prepared with %s required document lines.' % added_count
        )
    elif added_count:
        applicant.message_post(
            body='F-0003 Required Documents Checklist normalized. %s missing required document line(s) were added.' % added_count
        )
    else:
        applicant.message_post(
            body='F-0003 Required Documents Checklist already exists and is up to date.'
        )

action = {'type': 'ir.actions.client', 'tag': 'reload'}

submission_model = env['x_hr.applicant_required_document_submission'].sudo()

for rec in records.sudo():
    required_lines = rec.x_line_ids.filtered(lambda line: line.x_required)

    if not required_lines:
        raise Warning('This F-0003 checklist has no required document lines.')

    missing_lines = env['x_hr.applicant_required_document_line'].sudo()

    for line in required_lines:
        accepted_domain = [
            ('x_line_id', '=', line.id),
            ('x_state', '=', 'accepted'),
        ]

        if line.x_requires_attachment:
            accepted_domain.append(('x_attachment_id', '!=', False))

        accepted = submission_model.search(accepted_domain, order='x_reviewed_on desc, id desc', limit=1)

        if accepted:
            line_values = {
                'x_status': 'accepted',
                'x_latest_accepted_submission_id': accepted.id,
                'x_latest_accepted_attachment_id': accepted.x_attachment_id.id if accepted.x_attachment_id else False,
                'x_document_number': accepted.x_document_number or False,
                'x_issuing_authority': accepted.x_issuing_authority or False,
                'x_place_of_issue': accepted.x_place_of_issue or False,
                'x_issue_date': accepted.x_issue_date or False,
                'x_expiry_date': accepted.x_expiry_date or False,
                'x_qualification_type': accepted.x_qualification_type or False,
                'x_qualification_subject': accepted.x_qualification_subject or False,
                'x_date_of_birth': accepted.x_date_of_birth or False,
                'x_place_of_birth': accepted.x_place_of_birth or False,
                'x_country_of_birth_id': accepted.x_country_of_birth_id.id if accepted.x_country_of_birth_id else False,
                'x_family_paper_number': accepted.x_family_paper_number or False,
                'x_family_reference_number': accepted.x_family_reference_number or False,
                'x_next_of_kin_name': accepted.x_next_of_kin_name or False,
                'x_next_of_kin_phone': accepted.x_next_of_kin_phone or False,
                'x_blood_type': accepted.x_blood_type or False,
                'x_bank_name': accepted.x_bank_name or False,
                'x_bank_branch': accepted.x_bank_branch or False,
                'x_account_number': accepted.x_account_number or False,
                'x_iban': accepted.x_iban or False,
                'x_reviewed_by_user_id': accepted.x_reviewed_by_user_id.id or env.user.id,
                'x_reviewed_on': accepted.x_reviewed_on or datetime.datetime.now(),
            }
            line.write(line_values)
        else:
            latest_submission = submission_model.search([
                ('x_line_id', '=', line.id),
            ], order='id desc', limit=1)

            if latest_submission and latest_submission.x_state == 'rejected':
                target_status = 'resubmission_requested'
            elif latest_submission and latest_submission.x_state == 'submitted':
                target_status = 'submitted'
            else:
                target_status = 'missing'

            line.write({
                'x_status': target_status,
                'x_latest_accepted_submission_id': False,
                'x_latest_accepted_attachment_id': False,
            })
            missing_lines |= line

    if missing_lines:
        rec.write({
            'x_state': 'in_review',
            'x_reviewer_user_id': env.user.id,
        })
        rec.message_post(
            body='F-0003 checklist remains In Review. %s required document line(s) do not have accepted evidence submissions yet.' % len(missing_lines)
        )
    else:
        rec.write({
            'x_state': 'ready_for_pdf',
            'x_reviewer_user_id': env.user.id,
        })
        rec.message_post(
            body='F-0003 checklist is ready for PDF generation. All required document lines have accepted evidence submissions.'
        )

action = {'type': 'ir.actions.client', 'tag': 'reload'}
